package com.exelynt.booking.specification; import com.exelynt.booking.entity.*; import org.springframework.data.jpa.domain.Specification; import java.math.BigDecimal; public final class ReservationSpecifications { private ReservationSpecifications(){} public static Specification<Reservation> filter(User user,ReservationStatus status,BigDecimal min,BigDecimal max){ return (root,q,cb)->{var p=cb.conjunction(); if(user!=null)p=cb.and(p,cb.equal(root.get("user"),user)); if(status!=null)p=cb.and(p,cb.equal(root.get("status"),status)); if(min!=null)p=cb.and(p,cb.greaterThanOrEqualTo(root.get("price"),min)); if(max!=null)p=cb.and(p,cb.lessThanOrEqualTo(root.get("price"),max)); return p;};}}
